        DistrictType.DIPLOMATIC_QUARTER,
    }

    # Features that are destroyed when placing a district
    DESTRUCTIBLE_FEATURES: Set[str] = {
        "FEATURE_FOREST",   # Woods
        "FEATURE_JUNGLE",   # Rainforest
        "FEATURE_MARSH",    # Marsh
